    align-items: center;
    justify-content: center;
    gap: 10px;
  var SOFT_DROP_POINTS = 1; // per cell moved down by the player
  var HARD_DROP_POINTS = 2; // per cell dropped

  // ---- State ----
  var board;       // ROWS x COLS array of piece letters or null
  var current;     // { type, row, col, rot, shape, lockTicks, lockResets } or null
  var queue;       // upcoming piece letters, soonest first
  var bag;         // 7-bag for the random generator
  var score, level, lines, status;
  var timer = null;

  function emptyBoard() {
    var b = [];
    for (var r = 0; r < ROWS; r++) {
      var row = [];
      for (var c = 0; c < COLS; c++) row.push(null);
      b.push(row);
    }
    return b;
  }

  function randomPiece() {
    if (!bag || bag.length === 0) {
      bag = TYPES.slice();
      for (var i = bag.length - 1; i > 0; i--) {
        var j = Math.floor(Math.random() * (i + 1));
        var t = bag[i]; bag[i] = bag[j]; bag[j] = t;
      }
    }
    return bag.pop();
  }

  function sanitizeQueue(q) {
    if (!Array.isArray(q)) return [];
    return q.map(function (x) { return String(x).toUpperCase(); })
            .filter(function (x) { return TYPES.indexOf(x) !== -1; });
  }

  // Keep enough upcoming pieces to fill the preview.
  var PREVIEW_COUNT = 3;
  function fillQueue() {
    while (queue.length < PREVIEW_COUNT) queue.push(randomPiece());
  }

  function pieceCells(p, dRow, dCol) {
    var out = [];
    for (var i = 0; i < p.shape.length; i++) {
      out.push([p.row + p.shape[i][0] + (dRow || 0), p.col + p.shape[i][1] + (dCol || 0)]);
    }
    return out;
  }

  function fits(p, dRow, dCol) {
    var cells = pieceCells(p, dRow, dCol);
    for (var i = 0; i < cells.length; i++) {
      var r = cells[i][0], c = cells[i][1];
      if (c < 0 || c >= COLS || r >= ROWS) return false;
      if (r >= 0 && board[r][c]) return false;
    }
    return true;
  }

  function spawn() {
    fillQueue();
    var type = queue.shift();
    fillQueue();
    var p = {
      type: type, row: 0, col: SPAWN_COL[type], rot: 0, shape: SHAPES[type],
      lockTicks: 0, lockResets: 0
    };
    if (!fits(p, 0, 0)) {
  }

  // ---- Rendering (synchronous) ----
  var boardEl = document.getElementById("board");
  var overlayEl = document.getElementById("overlay");
  var scoreEl = document.getElementById("score");
  var levelEl = document.getElementById("level");
  var linesEl = document.getElementById("lines");
  var previewEl = document.getElementById("preview");
  var cellEls = [];
  var previewItems = []; // [{ el, cells }] one per upcoming piece

  (function buildDom() {
    for (var r = 0; r < ROWS; r++) {
      var row = [];
      for (var c = 0; c < COLS; c++) {
        var el = document.createElement("div");
        el.className = "cell";
        el.setAttribute("data-testid", "cell");
        el.setAttribute("data-row", String(r));
        el.setAttribute("data-col", String(c));
        el.setAttribute("data-filled", "false");
        el.setAttribute("data-piece", "");
        boardEl.insertBefore(el, overlayEl);
        row.push(el);
      }
      cellEls.push(row);
    }
    for (var i = 0; i < PREVIEW_COUNT; i++) {
      var item = document.createElement("div");
      item.className = "preview-item";
      item.setAttribute("data-testid", "next-piece-item");
      item.setAttribute("data-piece", "");
      var minis = [];
      for (var k = 0; k < 8; k++) {
        var m = document.createElement("div");
        m.className = "mini";
        item.appendChild(m);
        minis.push(m);
      }
      previewEl.appendChild(item);
      previewItems.push({ el: item, cells: minis });
    }
  })();

  function setCell(el, type) {
    var piece = type || "";
    if (el.getAttribute("data-piece") === piece) return;
    el.className = piece ? "cell p-" + piece : "cell";
    el.setAttribute("data-filled", piece ? "true" : "false");
    el.setAttribute("data-piece", piece);
  }

  function render() {
    var view = board.map(function (row) { return row.slice(); });
    if (current) {
      var cells = pieceCells(current, 0, 0);
      for (var i = 0; i < cells.length; i++) {
        var r = cells[i][0], c = cells[i][1];
        if (r >= 0 && r < ROWS && c >= 0 && c < COLS) view[r][c] = current.type;
      }
    }
    for (var rr = 0; rr < ROWS; rr++) {
      for (var cc = 0; cc < COLS; cc++) setCell(cellEls[rr][cc], view[rr][cc]);
    }

    scoreEl.textContent = String(score);
    levelEl.textContent = String(level);
    linesEl.textContent = String(lines);

    previewItems.forEach(function (item, idx) {
      var type = queue[idx] || "";
      item.el.setAttribute("data-piece", type);
      item.el.hidden = !type;
      for (var k = 0; k < item.cells.length; k++) item.cells[k].className = "mini";
      if (type) {
        SHAPES[type].forEach(function (off) {
          item.cells[off[0] * 4 + off[1]].className = "mini p-" + type;
        });
      }
    });

    overlayEl.hidden = status !== "gameover";
  }

  // ---- Game control ----
  function newGame(q) {
    board = emptyBoard();
    bag = [];
    queue = sanitizeQueue(q);
    score = 0;
    level = 1;
    lines = 0;
    status = "running";
    current = null;
    spawn();
    if (status === "running") startTimer();
    render();
  }

  function parseRows(rows) {
    ACTIONS[action]();
    render();
  });

  document.getElementById("restart").addEventListener("click", function () {
    newGame();
  });

  // ---- Test control surface ----
  window.__tetris = {
    newGame: function (q) { newGame(q); },
    setQueue: function (q) {
      queue = sanitizeQueue(q);
      fillQueue();
      render();
    },
    setBoard: function (rows) {
      board = parseRows(rows);
      render();
    },
    tick: function (n) {
      var count = n === undefined ? 1 : Math.max(0, Math.floor(Number(n)) || 0);
      for (var i = 0; i < count; i++) gravityStep();
      render();
    },
    input: function (action) {
      var fn = ACTIONS[action];
      if (!fn) return;
      fn();
      render();
    },
    getBoard: function () { return boardToRows(); },
    getState: function () {
      return {
        current: current ? { type: current.type, cells: pieceCells(current, 0, 0) } : null,
        next: queue.slice(),
        score: score,
        level: level,
        lines: lines,
        status: status
      };
    }
  };

  newGame();
})();
</script>
</body>
</html>

